"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import {
  type ComponentPropsWithoutRef,
  type FocusEvent,
  type KeyboardEvent,
  type ReactNode,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
} from "react";

import { cn } from "@/lib/utils";

/** One command the palette can run. */
export interface PaletteCommand {
  id: string;
  label: string;
  /** A short word on the right of the row, such as "Page" or "Action". The search reads it too. */
  hint?: string;
  /** Extra words the search matches but the row does not show. */
  keywords?: string[];
  icon?: ReactNode;
  onSelect?: () => void;
}

/** Props for a command palette. Pass `open` to control it, or `defaultOpen` to let it hold its own state. */
export type CommandPaletteProps = Omit<ComponentPropsWithoutRef<"div">, "children" | "onSelect"> & {
  commands: PaletteCommand[];
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Runs after the chosen command's own `onSelect`. */
  onSelect?: (command: PaletteCommand) => void;
  /** The text on the trigger. It also names the panel for screen readers. */
  triggerLabel?: string;
  placeholder?: string;
  emptyLabel?: string;
  /** Set to false when the page already binds Cmd or Ctrl with K, or holds a second palette. */
  shortcut?: boolean;
};

// Damping 60 is 2 × √900: critically damped and stiff, so the highlight keeps up with a held arrow key.
const GLIDE: Transition = { type: "spring", stiffness: 900, damping: 60, mass: 1 };
const ENTER: Transition = { duration: 0.2, ease: [0.165, 0.84, 0.44, 1] };
const EXIT: Transition = { duration: 0.12, ease: [0.165, 0.84, 0.44, 1] };
const INSTANT: Transition = { duration: 0 };

function SearchGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.75" aria-hidden="true" className="size-4 shrink-0">
      <circle cx="7" cy="7" r="4.25" />
      <path d="m10.25 10.25 3.25 3.25" strokeLinecap="round" />
    </svg>
  );
}

function EnterGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.75" aria-hidden="true" className="size-4 shrink-0">
      <path d="M12.5 3.5v4a2 2 0 0 1-2 2h-7m0 0 2.5-2.5M3.5 9.5 6 12" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

function matches(command: PaletteCommand, query: string) {
  const text = [command.label, command.hint ?? "", ...(command.keywords ?? [])].join(" ").toLowerCase();
  return query
    .toLowerCase()
    .split(/\s+/)
    .filter(Boolean)
    .every((word) => text.includes(word));
}

/**
 * A search box of commands that opens from its trigger or with Cmd or Ctrl and K.
 * The panel sits inside this component's own box instead of a page-wide layer,
 * so it works in a card, a sidebar or a toolbar.
 */
export function CommandPalette({
  commands,
  open,
  defaultOpen = false,
  onOpenChange,
  onSelect,
  triggerLabel = "Search commands",
  placeholder = "Type a command",
  emptyLabel = "No command matches",
  shortcut = true,
  className,
  ...divProps
}: CommandPaletteProps) {
  const [ownOpen, setOwnOpen] = useState(defaultOpen);
  const isOpen = open ?? ownOpen;
  const [query, setQuery] = useState("");
  const [active, setActive] = useState(0);
  const [highlight, setHighlight] = useState<{ y: number; height: number } | null>(null);
  // The key hint depends on the device, so it shows only once the browser has said which one this is.
  const [keys, setKeys] = useState<string | null>(null);
  const reduceMotion = useReducedMotion();
  const id = useId();
  const triggerRef = useRef<HTMLButtonElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLDivElement>(null);
  // Closing by Escape moves focus, and that blur asks to close again. The ref lets the second ask do nothing.
  const openNow = useRef(isOpen);
  const wasOpen = useRef(isOpen);

  const results = commands.filter((command) => matches(command, query));
  const activeIndex = Math.min(active, results.length - 1);
  const optionId = (command: PaletteCommand) => `${id}-option-${command.id}`;

  const changeOpen = (next: boolean) => {
    if (openNow.current === next) return;
    openNow.current = next;
    if (next) {
      setQuery("");
      setActive(0);
    }
    if (open === undefined) setOwnOpen(next);
    onOpenChange?.(next);
  };

  const closeToTrigger = () => {
    changeOpen(false);
    triggerRef.current?.focus();
  };

  const run = (command: PaletteCommand) => {
    command.onSelect?.();
    onSelect?.(command);
    closeToTrigger();
  };

  useEffect(() => {
    setKeys(/Mac|iPhone|iPad/.test(navigator.platform) ? "⌘K" : "Ctrl K");
  }, []);

  useEffect(() => {
    openNow.current = isOpen;
    // A palette that starts open must not pull focus away from the page as it loads.
    if (isOpen && !wasOpen.current) inputRef.current?.focus();
    wasOpen.current = isOpen;
  }, [isOpen]);

  useEffect(() => {
    if (!shortcut) return;
    const onKey = (event: globalThis.KeyboardEvent) => {
      if (!(event.metaKey || event.ctrlKey) || event.key.toLowerCase() !== "k") return;
      event.preventDefault();
      if (openNow.current) closeToTrigger();
      else changeOpen(true);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  });

  // The highlight is one element that travels, so it needs the active row's place in the list.
  useLayoutEffect(() => {
    const list = listRef.current;
    const row = list?.querySelector<HTMLElement>('[aria-selected="true"]');
    if (!isOpen || !list || !row) {
      setHighlight(null);
      return;
    }
    // A row measures from the listbox, and the listbox sits inside the list's padding.
    const inset = row.parentElement?.offsetTop ?? 0;
    const top = row.offsetTop + inset;
    const bottom = top + row.offsetHeight;
    setHighlight({ y: top, height: row.offsetHeight });
    // Scroll only the list. `scrollIntoView` can also scroll the page under the palette.
    // The padding stays in view, so the first and the last row never touch the edge.
    if (top - inset < list.scrollTop) list.scrollTop = top - inset;
    if (bottom + inset > list.scrollTop + list.clientHeight) list.scrollTop = bottom + inset - list.clientHeight;
  }, [isOpen, activeIndex, query, commands]);

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const step = { ArrowDown: 1, ArrowUp: -1 }[event.key];
    if (step && results.length > 0) {
      event.preventDefault();
      setActive((activeIndex + step + results.length) % results.length);
    } else if (event.key === "Enter" && results[activeIndex]) {
      event.preventDefault();
      run(results[activeIndex]);
    } else if (event.key === "Escape") {
      event.preventDefault();
      closeToTrigger();
    }
  };

  const onBlur = (event: FocusEvent<HTMLDivElement>) => {
    if (!event.currentTarget.contains(event.relatedTarget)) changeOpen(false);
  };

  const hidden = reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.96 };

  return (
    <div {...divProps} className={cn("relative w-full max-w-sm", className)}>
      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="dialog"
        aria-expanded={isOpen}
        aria-keyshortcuts={shortcut ? "Meta+K Control+K" : undefined}
        onClick={() => changeOpen(true)}
        className="flex min-h-11 w-full cursor-pointer touch-manipulation items-center gap-2 rounded-xl border border-border bg-card px-3 text-sm text-muted-foreground outline-none hover:bg-muted focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background motion-safe:transition-colors motion-safe:duration-150"
      >
        <SearchGlyph />
        <span className="flex-1 text-left">{triggerLabel}</span>
        {shortcut && keys ? (
          <kbd aria-hidden="true" className="rounded-md border border-border bg-muted px-1.5 py-0.5 font-sans text-xs whitespace-nowrap">
            {keys}
          </kbd>
        ) : null}
      </button>
      <AnimatePresence initial={false}>
        {isOpen ? (
          <motion.div
            key="panel"
            role="dialog"
            aria-label={triggerLabel}
            initial={hidden}
            animate={{ opacity: 1, scale: 1, transition: ENTER }}
            // The leaving panel takes no clicks, so a fast second click reaches the trigger under it.
            exit={{ ...hidden, pointerEvents: "none", transition: EXIT }}
            onKeyDown={onKeyDown}
            onBlur={onBlur}
            // The panel covers the trigger and grows from its top edge, so it reads as the trigger opening.
            className="absolute inset-x-0 top-0 z-10 origin-top overflow-hidden rounded-xl border border-border bg-card shadow-lg"
          >
            <div className="flex min-h-11 items-center gap-2 border-b border-border px-3 text-muted-foreground">
              <SearchGlyph />
              <input
                ref={inputRef}
                type="text"
                role="combobox"
                aria-label={triggerLabel}
                aria-expanded="true"
                aria-controls={`${id}-list`}
                aria-autocomplete="list"
                aria-activedescendant={results[activeIndex] ? optionId(results[activeIndex]) : undefined}
                autoComplete="off"
                spellCheck={false}
                placeholder={placeholder}
                value={query}
                onChange={(event) => {
                  setQuery(event.target.value);
                  setActive(0);
                }}
                // The panel shows focus, and a ring inside its top edge would be cut off.
                className="h-11 min-w-0 flex-1 bg-transparent text-base text-foreground outline-none placeholder:text-muted-foreground sm:text-sm"
              />
            </div>
            {/* The height holds whole rows: three on a touch screen, four with a pointer. */}
            <div ref={listRef} className="relative max-h-35 overflow-y-auto p-1 sm:max-h-38">
              {highlight ? (
                <motion.span
                  aria-hidden="true"
                  initial={false}
                  animate={highlight}
                  transition={reduceMotion ? INSTANT : GLIDE}
                  className="pointer-events-none absolute inset-x-1 top-0 rounded-lg bg-muted"
                />
              ) : null}
              <ul
                id={`${id}-list`}
                role="listbox"
                aria-label={triggerLabel}
                // A press on a row must not take focus from the input, or the panel would close before the click lands.
                onMouseDown={(event) => event.preventDefault()}
                className="relative"
              >
                {results.map((command, index) => (
                  <li
                    key={command.id}
                    id={optionId(command)}
                    role="option"
                    aria-selected={index === activeIndex}
                    onPointerMove={() => setActive(index)}
                    onClick={() => run(command)}
                    className="flex min-h-11 cursor-pointer items-center gap-3 rounded-lg px-2 text-sm text-foreground sm:min-h-9"
                  >
                    {command.icon ? (
                      <span aria-hidden="true" className="flex size-4 shrink-0 items-center justify-center text-muted-foreground">
                        {command.icon}
                      </span>
                    ) : null}
                    <span className="min-w-0 flex-1 truncate">{command.label}</span>
                    {command.hint ? <span className="text-xs text-muted-foreground">{command.hint}</span> : null}
                    {/* The key glyph marks the row Enter will run, so the highlight is not the only sign. */}
                    <span className={cn("flex text-muted-foreground", index === activeIndex ? "opacity-100" : "opacity-0")}>
                      <EnterGlyph />
                    </span>
                  </li>
                ))}
              </ul>
              <p role="status" className={results.length > 0 ? "sr-only" : "px-2 py-6 text-center text-sm text-muted-foreground"}>
                {results.length > 0 ? `${results.length} ${results.length === 1 ? "command" : "commands"}` : emptyLabel}
              </p>
            </div>
          </motion.div>
        ) : null}
      </AnimatePresence>
    </div>
  );
}
